package com.cpf.starter.cache.valkey;import org.springframework.boot.actuate.health.Health;import org.springframework.boot.actuate.health.HealthIndicator;import org.springframework.boot.autoconfigure.AutoConfiguration;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.boot.context.properties.EnableConfigurationProperties;import org.springframework.context.annotation.Bean;import org.springframework.data.redis.connection.RedisConnectionFactory;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.data.redis.listener.RedisMessageListenerContainer;
@AutoConfiguration @EnableConfigurationProperties(CpfValkeyProperties.class) @ConditionalOnProperty(prefix="cpf.cache.valkey",name="enabled",havingValue="true") public class CpfValkeyAutoConfiguration {
 @Bean StringRedisTemplate cpfValkeyTemplate(RedisConnectionFactory f){return new StringRedisTemplate(f);}@Bean RedisMessageListenerContainer cpfValkeyListenerContainer(RedisConnectionFactory f){var c=new RedisMessageListenerContainer();c.setConnectionFactory(f);return c;}@Bean CpfValkeyCache cpfValkeyCache(StringRedisTemplate t,CpfValkeyProperties p){p.validate();return new CpfValkeyCache(t,p);}@Bean("cpfValkeyHealthIndicator") HealthIndicator health(RedisConnectionFactory f){return ()->{try(var c=f.getConnection()){return "PONG".equalsIgnoreCase(c.ping())?Health.up().build():Health.down().build();}catch(Exception ex){return Health.down(ex).build();}};}}
